#include <bits/stdc++.h>
using namespace std;
long long n;
set<long long> s;
void dfs(long long cur, int x, int y, int depth){
    if(cur > n) return;
    if(cur > 0) s.insert(cur);
    if(depth >= 10) return;
    dfs(cur*10+x, x, y, depth+1);
    if(y != x) dfs(cur*10+y, x, y, depth+1);
}
int main(){
    cin >> n;
    for(int x=0;x<=9;x++)
        for(int y=x;y<=9;y++)
            dfs(0,x,y,0);
    cout << s.size() << endl;
    return 0;
}
